import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.StringTokenizer;

public class Main {
    static class FastReader {
        BufferedReader br;
        StringTokenizer st;

        public FastReader() {
            br = new BufferedReader(new InputStreamReader(System.in));
        }

        String next() {
            while (st == null || !st.hasMoreElements()) {
                try {
                    String line = br.readLine();
                    if (line == null) return null;
                    st = new StringTokenizer(line);
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return st.nextToken();
        }

        int nextInt() {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) {
        FastReader in = new FastReader();
        String sStr = in.next();
        if (sStr == null) return;
        int S = Integer.parseInt(sStr);
        int T = in.nextInt();

        boolean[][] adj = new boolean[S + 1][S + 1];

        for (int i = 0; i < T; i++) {
            int u = in.nextInt();
            int v = in.nextInt();
            adj[u][v] = true;
            adj[v][u] = true;
        }

        int P = in.nextInt();
        int validWalks = 0;

        for (int i = 0; i < P; i++) {
            int n = in.nextInt();
            int[] path = new int[n];
            for (int j = 0; j < n; j++) {
                path[j] = in.nextInt();
            }

            boolean possible = true;
            for (int j = 0; j < n - 1; j++) {
                if (!adj[path[j]][path[j + 1]]) {
                    possible = false;
                    break;
                }
            }

            if (possible) {
                validWalks++;
            }
        }

        System.out.println(validWalks);
    }
}
